<script setup lang="ts">
import { Head, Link } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import RaceClock from '../../Components/RaceClock.vue';
import { formatDuration } from '../../lib';
interface Athlete { id:number; full_name:string; first_name:string; last_name:string }
interface Timing { id:number; elapsed_ms:number; checkpoint:{id:number;name:string;discipline?:string;kind:string;sequence:number} }
interface Member { id:number; discipline:string; athlete:Athlete }
interface Entry { id:number; bib_number:string; type:string; team_name?:string; race:{id:number;name:string;event_date:string;status:string;started_at?:string|null;finished_at?:string|null}; members:Member[]; timings:Timing[] }
defineProps<{ athlete:Athlete; entries:Entry[]; serverNow:string }>();
